-- blog_posts never had a migration in this repo at all (same class of gap as
-- watchlist/portfolios/ai_conversations found earlier) -- src/lib/blog.functions.ts
-- has queried it all along with nothing here to create it. Public read (it's a
-- public blog), write restricted to the single owner identity already used to
-- gate blog authoring client-side (src/lib/admin.ts) and community moderation
-- (20260726090000_update-admin-email.sql) -- same email, so this is real
-- server-side enforcement, not just a client-side UI gate.
CREATE TABLE IF NOT EXISTS public.blog_posts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  excerpt TEXT NOT NULL,
  content TEXT NOT NULL,
  source_name TEXT,
  source_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
GRANT SELECT ON public.blog_posts TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.blog_posts TO authenticated;
GRANT ALL ON public.blog_posts TO service_role;
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "blog posts public read" ON public.blog_posts;
CREATE POLICY "blog posts public read" ON public.blog_posts FOR SELECT USING (true);
DROP POLICY IF EXISTS "blog posts owner insert" ON public.blog_posts;
CREATE POLICY "blog posts owner insert" ON public.blog_posts FOR INSERT WITH CHECK ((auth.jwt() ->> 'email') = 'admin@s-markets.com');
DROP POLICY IF EXISTS "blog posts owner update" ON public.blog_posts;
CREATE POLICY "blog posts owner update" ON public.blog_posts FOR UPDATE USING ((auth.jwt() ->> 'email') = 'admin@s-markets.com');
DROP POLICY IF EXISTS "blog posts owner delete" ON public.blog_posts;
CREATE POLICY "blog posts owner delete" ON public.blog_posts FOR DELETE USING ((auth.jwt() ->> 'email') = 'admin@s-markets.com');

-- Initial seed: 6 original educational articles, expanded from the Learn
